<?php require_once __DIR__.'/includes/auth.php';$message='';if($_SERVER['REQUEST_METHOD']==='POST'){try{$role=db()->query("SELECT id FROM roles WHERE name='Admin'")->fetchColumn();$s=db()->prepare('INSERT INTO users(full_name,username,email,password,role_id) VALUES(?,?,?,?,?)');$s->execute(['System Administrator','admin','admin@lda.gov.in',password_hash('admin123',PASSWORD_BCRYPT),$role]);$message='Admin created. Delete create_admin.php now.';}catch(Throwable $e){$message='Admin may already exist or database is not imported.';}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create admin</title><link rel="stylesheet" href="assets/css/style.css"></head><body><main class="login-wrap"><section class="form-card login-card"><h1>Initial administrator</h1><p class="muted">Creates admin / admin123 with a bcrypt password hash.</p><?php if($message):?><div class="alert"><?=e($message)?></div><?php endif;?><form method="post"><button class="btn btn-primary">Create administrator</button></form></section></main></body></html>